package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.ExternalTypeHandler;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for ExternalTypeHandler.Builder#build()
 */
public class Builder_build_TriageGen1Test {



    @Test
    public void testBuild_WithProperties() throws Exception {
        // Arrange
        ExternalTypeHandler.Builder builder = new ExternalTypeHandler.Builder();

        // Since SettableBeanProperty and TypeDeserializer are complex, 
        // we use the public method addExternal to populate the internal state.
        // We use nulls for the arguments as the build() method doesn't appear to 
        // validate them for the constructor call provided in the snippet.
        builder.addExternal(null, null);

        // Act
        ExternalTypeHandler result = builder.build();

        // Assert
        assertNotNull("The built ExternalTypeHandler should not be null", result);

        // Verify internal state via reflection to ensure properties were passed correctly
        // This ensures we cover the logic of converting _properties to array and using _nameToPropertyIndex
        Field propertiesField = ExternalTypeHandler.class.getDeclaredField("_properties");
        propertiesField.setAccessible(true);
        Object[] propertiesArray = (Object[]) propertiesField.get(result);

        assertNotNull(propertiesArray);
    }


}

package com.fasterxml.jackson.databind.deser.impl;

