/**
 * Unit tests for ExternalTypeHandler.Builder#build()
 */
public class Builder_build_TriageGen1Test {





    @Test
    public void testBuild_MultipleProperties() throws Exception {
        // Arrange
        ExternalTypeHandler.Builder builder = new ExternalTypeHandler.Builder();
        builder.addExternal(null, null);
        builder.addExternal(null, null);

        // Act
        ExternalTypeHandler result = builder.build();

        // Assert
        assertNotNull(result);

        Field propertiesField = ExternalTypeHandler.class.getDeclaredField("_properties");
        propertiesField.setAccessible(true);
        Object[] propertiesArray = (Object[]) propertiesField.get(result);

        // Based on the build() implementation, it should contain the elements added
        assertNotNull(propertiesArray);
    }
